using ManpowerManagement.Data;using ManpowerManagement.Models;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;
namespace ManpowerManagement.Pages.Admin;
public class SetupModel(AppDbContext db,UserManager<ApplicationUser> users):PageModel{public List<SelectListItem> Workshops{get;set;}=[];[TempData]public string? Message{get;set;}public async Task OnGetAsync()=>Workshops=await db.Workshops.OrderBy(x=>x.Name).Select(x=>new SelectListItem(x.Name,x.Id.ToString())).ToListAsync();public async Task<IActionResult> OnPostUserAsync(string username,string password){var u=new ApplicationUser{UserName=username};var r=await users.CreateAsync(u,password);if(r.Succeeded)await users.AddToRoleAsync(u,Roles.Approver);Message=r.Succeeded?"Approver created.":string.Join("; ",r.Errors.Select(x=>x.Description));return RedirectToPage();}public async Task<IActionResult> OnPostCalendarAsync(int workshopId,DateOnly workDate){var c=await db.WorkCalendars.SingleOrDefaultAsync(x=>x.WorkshopId==workshopId&&x.WorkDate==workDate);if(c==null)db.WorkCalendars.Add(new WorkCalendar{WorkshopId=workshopId,WorkDate=workDate,IsWorkingDay=true});else c.IsWorkingDay=true;await db.SaveChangesAsync();Message="Calendar updated.";return RedirectToPage();}}
